1566	/* ServiceSearch PDU, ref to BT Core 5.4, Vol 3, part B, 4.5.1 */
1567	static int sdp_client_ss_search(struct bt_sdp_client *session,
1568					const struct bt_sdp_discover_params *param)
1569	{
1570		struct net_buf *buf;
1571	
1572		buf = bt_sdp_create_pdu();
1573	
1574		/* BT_SDP_SEQ8 means length of sequence is on additional next byte */
1575		net_buf_add_u8(buf, BT_SDP_SEQ8);
1576	
1577		switch (param->uuid->type) {
1578		case BT_UUID_TYPE_16:
1579			/* Seq length */
1580			net_buf_add_u8(buf, 0x03);
1581			/* Seq type */
1582			net_buf_add_u8(buf, BT_SDP_UUID16);
1583			/* Seq value */
1584			net_buf_add_be16(buf, BT_UUID_16(param->uuid)->val);
1585			break;
1586		case BT_UUID_TYPE_32:
1587			net_buf_add_u8(buf, 0x05);
1588			net_buf_add_u8(buf, BT_SDP_UUID32);
1589			net_buf_add_be32(buf, BT_UUID_32(param->uuid)->val);
1590			break;
1591		case BT_UUID_TYPE_128:
1592			net_buf_add_u8(buf, 0x11);
1593			net_buf_add_u8(buf, BT_SDP_UUID128);
1594			net_buf_add_mem(buf, BT_UUID_128(param->uuid)->val,
1595					ARRAY_SIZE(BT_UUID_128(param->uuid)->val));
1596			break;
1597		default:
1598			LOG_ERR("Unknown UUID type %u", param->uuid->type);
1599			return -EINVAL;
1600		}
1601	
1602		/* Set maximum number of service record handles */
1603		net_buf_add_be16(buf, net_buf_tailroom(session->rec_buf) / SDP_RECORD_HANDLE_SIZE);
1604		/*
1605		 * Update and validate PDU ContinuationState. Initial SSA Request has
1606		 * zero length continuation state since no interaction has place with
1607		 * server so far, otherwise use the original state taken from remote's
1608		 * last response PDU that is cached by SDP client context.
1609		 */
1610		if (session->cstate.length == 0U) {
1611			net_buf_add_u8(buf, 0x00);
1612		} else {
1613			net_buf_add_u8(buf, session->cstate.length);
1614			net_buf_add_mem(buf, session->cstate.data, session->cstate.length);
1615		}
1616	
1617		/* Update context param to the one being resolving now */
1618		session->param = param;
1619		session->tid++;
1620	
1621		return bt_sdp_send(&session->chan.chan, buf, BT_SDP_SVC_SEARCH_REQ, session->tid);
1622	}
