1586		case BT_UUID_TYPE_32:
1587			net_buf_add_u8(buf, 0x05);
1588			net_buf_add_u8(buf, BT_SDP_UUID32);
1589			net_buf_add_be32(buf, BT_UUID_32(param->uuid)->val);
1590			break;
1591		case BT_UUID_TYPE_128:
1592			net_buf_add_u8(buf, 0x11);
