1611			net_buf_add_u8(buf, 0x00);
1612		} else {
1613			net_buf_add_u8(buf, session->cstate.length);
1614			net_buf_add_mem(buf, session->cstate.data, session->cstate.length);
1615		}
1616	
1617		/* Update context param to the one being resolving now */
1618		session->param = param;
1619		session->tid++;
1620	
1621		return bt_sdp_send(&session->chan.chan, buf, BT_SDP_SVC_SEARCH_REQ, session->tid);
1622	}
