1743	static int sdp_client_discover(struct bt_sdp_client *session)
1744	{
1745		const struct bt_sdp_discover_params *param;
1746		int err;
1747	
1748		/*
1749		 * Select proper user params, if session->param is invalid it means
1750		 * getting new UUID from top of to be resolved params list. Otherwise
1751		 * the context is in a middle of partial SDP PDU responses and cached
1752		 * value from context can be used.
1753		 */
1754		if (!session->param) {
1755			param = GET_PARAM(sys_slist_peek_head(&session->reqs));
1756		} else {
1757			param = session->param;
1758		}
1759	
1760		if (param != NULL && session->rec_buf == NULL) {
1761			session->rec_buf = net_buf_alloc(param->pool, K_FOREVER);
1762		}
1763	
1764		if (param == NULL || session->rec_buf == NULL) {
1765			struct bt_l2cap_chan *chan = &session->chan.chan;
1766	
1767			LOG_WRN("No more request, disconnect channel");
1768			/* No UUID items, disconnect channel */
1769			return bt_l2cap_chan_disconnect(chan);
1770		}
1771	
1772		switch (param->type) {
1773		case BT_SDP_DISCOVER_SERVICE_SEARCH:
1774			err = sdp_client_ss_search(session, param);
1775			break;
1776		case BT_SDP_DISCOVER_SERVICE_ATTR:
1777			err = sdp_client_sa_search(session, param);
1778			break;
1779		case BT_SDP_DISCOVER_SERVICE_SEARCH_ATTR:
1780			err = sdp_client_ssa_search(session, param);
1781			break;
1782		default:
1783			err = -EINVAL;
1784			break;
1785		}
1786	
1787		if (err) {
1788			/* Get next UUID and start resolving it */
1789			sdp_client_params_iterator(session);
1790		}
1791	
1792		return 0;
1793	}
1794	
1795	static void sdp_client_params_iterator(struct bt_sdp_client *session)
1796	{
1797		struct bt_l2cap_chan *chan = &session->chan.chan;
1798		struct bt_sdp_discover_params *param, *tmp;
1799	
1800		SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&session->reqs, param, tmp, _node) {
1801			if (param != session->param) {
1802				continue;
1803			}
1804	
1805			LOG_DBG("");
1806	
1807			/* Remove already checked UUID node */
1808			sys_slist_remove(&session->reqs, NULL, &param->_node);
1809			/* Invalidate cached param in context */
1810			session->param = NULL;
1811			if (session->rec_buf != NULL) {
1812				net_buf_unref(session->rec_buf);
1813				session->rec_buf = NULL;
1814			}
1815			/* Reset continuation state in current context */
1816			(void)memset(&session->cstate, 0, sizeof(session->cstate));
1817	
1818			/* Check if there's valid next UUID */
1819			if (!sys_slist_is_empty(&session->reqs)) {
1820				sdp_client_discover(session);
1821				return;
1822			}
1823	
1824			/* No UUID items, disconnect channel */
1825			bt_l2cap_chan_disconnect(chan);
1826			break;
1827		}
1828	}
