1830	static uint16_t sdp_client_get_total(struct bt_sdp_client *session,
1831					  struct net_buf *buf, uint16_t *total)
1832	{
1833		uint16_t pulled;
1834		uint8_t seq;
1835	
1836		/*
1837		 * Pull value of total octets of all attributes available to be
1838		 * collected when response gets completed for given UUID. Such info can
1839		 * be get from the very first response frame after initial SSA request
1840		 * was sent. For subsequent calls related to the same SSA request input
1841		 * buf and in/out function parameters stays neutral.
1842		 */
1843		if (session->cstate.length == 0U) {
1844			seq = net_buf_pull_u8(buf);
1845			pulled = 1U;
1846			switch (seq) {
1847			case BT_SDP_SEQ8:
1848				*total = net_buf_pull_u8(buf);
1849				pulled += 1U;
1850				break;
1851			case BT_SDP_SEQ16:
1852				*total = net_buf_pull_be16(buf);
1853				pulled += 2U;
1854				break;
1855			case BT_SDP_SEQ32:
1856				*total = net_buf_pull_be32(buf);
1857				pulled += 4U;
1858				break;
1859			default:
1860				LOG_WRN("Sequence type 0x%02x not handled", seq);
1861				*total = 0U;
1862				break;
1863			}
1864	
1865			LOG_DBG("Total %u octets of all attributes", *total);
1866		} else {
1867			pulled = 0U;
1868			*total = 0U;
1869		}
1870	
1871		return pulled;
1872	}
