1945					     enum uuid_state state)
1946	{
1947		struct bt_conn *conn = session->chan.chan.conn;
1948		struct bt_sdp_client_result result;
1949		uint16_t rec_len;
1950		uint8_t user_ret;
1951	
1952		if (state == UUID_NOT_RESOLVED) {
1953			result.resp_buf = NULL;
1954			result.next_record_hint = false;
1955			session->param->func(conn, &result, session->param);
1956			return;
1957		}
1958	
1959		while (session->rec_buf->len) {
1960			struct net_buf_simple_state buf_state;
1961	
1962			rec_len = get_record_len(session);
1963			/* tell the user about multi record resolution */
1964			if (session->rec_buf->len > rec_len) {
1965				result.next_record_hint = true;
1966			} else {
1967				result.next_record_hint = false;
1968			}
1969	
1970			/* save the original session buffer */
1971			net_buf_simple_save(&session->rec_buf->b, &buf_state);
1972			/* initialize internal result buffer instead of memcpy */
1973			result.resp_buf = session->rec_buf;
1974			/*
1975			 * Set user internal result buffer length as same as record
1976			 * length to fake user. User will see the individual record
1977			 * length as rec_len instead of whole session rec_buf length.
1978			 */
1979			result.resp_buf->len = rec_len;
1980	
1981			user_ret = session->param->func(conn, &result, session->param);
1982	
1983			/* restore original session buffer */
1984			net_buf_simple_restore(&session->rec_buf->b, &buf_state);
1985			/*
1986			 * sync session buffer data length with next record chunk not
1987			 * send to user so far
1988			 */
1989			net_buf_pull(session->rec_buf, rec_len);
1990			if (user_ret == BT_SDP_DISCOVER_UUID_STOP) {
1991				break;
1992			}
1993		}
1994	}
