1996	static int sdp_client_receive_ss(struct bt_sdp_client *session, struct net_buf *buf)
1997	{
1998		struct bt_sdp_pdu_cstate *cstate;
1999		uint16_t current_count;
2000		uint16_t total_count;
2001		uint32_t record_len;
2002		uint32_t received_count;
2003	
2004		/* Check the buffer len for the total_count field */
2005		if (buf->len < sizeof(total_count)) {
2006			LOG_ERR("Invalid frame payload length");
2007			return 0;
2008		}
2009	
2010		/* Get total service record count. */
2011		total_count = net_buf_pull_be16(buf);
2012	
2013		/* Check the buffer len for the current_count field */
2014		if (buf->len < sizeof(current_count)) {
2015			LOG_ERR("Invalid frame payload length");
2016			return 0;
2017		}
2018	
2019		/* Get current service record count. */
2020		current_count = net_buf_pull_be16(buf);
2021		/* Check valid of current service record count */
2022		if (current_count > total_count) {
2023			LOG_ERR("Invalid current service record count");
2024			return 0;
2025		}
2026	
2027		received_count = session->rec_buf->len / SDP_RECORD_HANDLE_SIZE;
2028		if ((received_count + current_count) > total_count) {
2029			LOG_ERR("Excess data received");
2030			return 0;
2031		}
2032	
2033		record_len = current_count * SDP_RECORD_HANDLE_SIZE;
2034		if (record_len >= buf->len) {
2035			LOG_ERR("Invalid packet");
2036			return 0;
2037		}
2038	
2039		/* Get PDU continuation state */
2040		cstate = (struct bt_sdp_pdu_cstate *)(buf->data + record_len);
2041	
2042		if (cstate->length > BT_SDP_MAX_PDU_CSTATE_LEN) {
2043			LOG_ERR("Invalid SDP PDU Continuation State length %u", cstate->length);
2044			return 0;
2045		}
2046	
2047		if ((record_len + SDP_CONT_STATE_LEN_SIZE + cstate->length) > buf->len) {
2048			LOG_ERR("Invalid payload length");
2049			return 0;
2050		}
2051	
2052		/*
2053		 * No record found for given UUID. The check catches case when
2054		 * current response frame has Continuation State shortest and
2055		 * valid and this is the first response frame as well.
2056		 */
2057		if (!current_count && cstate->length == 0U && session->cstate.length == 0U) {
2058			LOG_DBG("Service record handle 0x%x not found", session->param->handle);
2059			/* Call user UUID handler */
2060			sdp_client_notify_result(session, UUID_NOT_RESOLVED);
2061			net_buf_pull(buf, sizeof(cstate->length));
2062			goto iterate;
2063		}
2064	
2065		if (record_len > net_buf_tailroom(session->rec_buf)) {
2066			LOG_WRN("Not enough room for getting records data");
2067			goto iterate;
2068		}
2069	
2070		net_buf_add_mem(session->rec_buf, buf->data, record_len);
2071		net_buf_pull(buf, record_len);
2072	
2073		/* check if current response says there's next portion to be fetched */
2074		if (cstate->length) {
2075			/* Cache original Continuation State in context */
2076			memcpy(&session->cstate, cstate, sizeof(struct bt_sdp_pdu_cstate));
2077	
2078			net_buf_pull(buf, cstate->length + sizeof(cstate->length));
2079	
2080			/* Request for next portion of attributes data */
2081			return sdp_client_discover(session);
2082		}
2083	
2084		net_buf_pull(buf, sizeof(cstate->length));
2085	
2086		LOG_DBG("UUID 0x%s resolved", bt_uuid_str(session->param->uuid));
2087		sdp_client_notify_result(session, UUID_RESOLVED);
2088	iterate:
2089		/* Get next UUID and start resolving it */
2090		sdp_client_params_iterator(session);
2091	
2092		return 0;
2093	}
