2179	static int sdp_client_receive(struct bt_l2cap_chan *chan, struct net_buf *buf)
2180	{
2181		struct bt_sdp_client *session = SDP_CLIENT_CHAN(chan);
2182		struct bt_sdp_hdr *hdr;
2183		uint16_t len, tid;
2184	
2185		LOG_DBG("session %p buf %p", session, buf);
2186	
2187		if (buf->len < sizeof(*hdr)) {
2188			LOG_ERR("Too small SDP PDU");
2189			return 0;
2190		}
2191	
2192		hdr = net_buf_pull_mem(buf, sizeof(*hdr));
2193		len = sys_be16_to_cpu(hdr->param_len);
2194		tid = sys_be16_to_cpu(hdr->tid);
2195	
2196		LOG_DBG("SDP PDU tid %u len %u", tid, len);
2197	
2198		if (buf->len != len) {
2199			LOG_ERR("SDP PDU length mismatch (%u != %u)", buf->len, len);
2200			return 0;
2201		}
2202	
2203		if (tid != session->tid) {
2204			LOG_ERR("Mismatch transaction ID value in SDP PDU");
2205			return 0;
2206		}
2207	
2208		switch (hdr->op_code) {
2209		case BT_SDP_SVC_SEARCH_RSP:
2210			return sdp_client_receive_ss(session, buf);
2211		case BT_SDP_SVC_ATTR_RSP:
2212			__fallthrough;
2213		case BT_SDP_SVC_SEARCH_ATTR_RSP:
2214			return sdp_client_receive_ssa_sa(session, buf);
2215		case BT_SDP_ERROR_RSP:
2216			LOG_INF("Invalid SDP request");
2217			sdp_client_notify_result(session, UUID_NOT_RESOLVED);
2218			sdp_client_params_iterator(session);
2219			return 0;
2220		default:
2221			LOG_DBG("PDU 0x%0x response not handled", hdr->op_code);
2222			break;
2223		}
2224	
2225		return 0;
2226	}
