2905	static int sdp_get_u16_data(const struct bt_sdp_attr_item *attr, uint16_t *u16)
2906	{
2907		const uint8_t *p;
2908	
2909		if (!u16) {
2910			LOG_ERR("Invalid pointer.");
2911			return -EINVAL;
2912		}
2913	
2914		/* assert 16bit can be read safely */
2915		if (attr->len != (sizeof(uint8_t) + sizeof(*u16))) {
2916			LOG_ERR("Invalid data length %u", attr->len);
2917			return -EMSGSIZE;
2918		}
2919	
2920		p = attr->val;
2921		__ASSERT(p != NULL, "attr->val cannot be NULL");
2922		if (p[0] != BT_SDP_UINT16) {
2923			LOG_ERR("Invalid DTD 0x%02x", p[0]);
2924			return -EINVAL;
2925		}
2926	
2927		*u16 = sys_get_be16(++p);
2928	
2929		return 0;
2930	}
