2095	static int sdp_client_receive_ssa_sa(struct bt_sdp_client *session, struct net_buf *buf)
2096	{
2097		struct bt_sdp_pdu_cstate *cstate;
2098		uint16_t frame_len;
2099		uint16_t total;
2100	
2101		/* Check the buffer len for the frame_len field */
2102		if (buf->len < sizeof(frame_len)) {
2103			LOG_ERR("Invalid frame payload length");
2104			return 0;
2105		}
2106	
2107		/* Get number of attributes in this frame. */
2108		frame_len = net_buf_pull_be16(buf);
2109		/* Check valid buf len for attribute list and cont state */
2110		if (buf->len < frame_len + SDP_CONT_STATE_LEN_SIZE) {
2111			LOG_ERR("Invalid frame payload length");
2112			return 0;
2113		}
2114		/* Check valid range of attributes length */
2115		if (frame_len < 2) {
2116			LOG_ERR("Invalid attributes data length");
2117			return 0;
2118		}
2119	
2120		/* Get PDU continuation state */
2121		cstate = (struct bt_sdp_pdu_cstate *)(buf->data + frame_len);
2122	
2123		if (cstate->length > BT_SDP_MAX_PDU_CSTATE_LEN) {
2124			LOG_ERR("Invalid SDP PDU Continuation State length %u", cstate->length);
2125			return 0;
2126		}
2127	
2128		if ((frame_len + SDP_CONT_STATE_LEN_SIZE + cstate->length) > buf->len) {
2129			LOG_ERR("Invalid frame payload length");
2130			return 0;
2131		}
2132	
2133		/*
2134		 * No record found for given UUID. The check catches case when
2135		 * current response frame has Continuation State shortest and
2136		 * valid and this is the first response frame as well.
2137		 */
2138		if (frame_len == 2U && cstate->length == 0U && session->cstate.length == 0U) {
2139			LOG_DBG("Record for UUID 0x%s not found", bt_uuid_str(session->param->uuid));
2140			/* Call user UUID handler */
2141			sdp_client_notify_result(session, UUID_NOT_RESOLVED);
2142			net_buf_pull(buf, frame_len + sizeof(cstate->length));
2143			goto iterate;
2144		}
2145	
2146		/* Get total value of all attributes to be collected */
2147		frame_len -= sdp_client_get_total(session, buf, &total);
2148	
2149		if (total > net_buf_tailroom(session->rec_buf)) {
2150			LOG_WRN("Not enough room for getting records data");
2151			goto iterate;
2152		}
2153	
2154		net_buf_add_mem(session->rec_buf, buf->data, frame_len);
2155		net_buf_pull(buf, frame_len);
2156	
2157		/* check if current response says there's next portion to be fetched */
2158		if (cstate->length) {
2159			/* Cache original Continuation State in context */
2160			memcpy(&session->cstate, cstate, sizeof(struct bt_sdp_pdu_cstate));
2161	
2162			net_buf_pull(buf, cstate->length + sizeof(cstate->length));
2163	
2164			/* Request for next portion of attributes data */
2165			return sdp_client_discover(session);
2166		}
2167	
2168		net_buf_pull(buf, sizeof(cstate->length));
2169	
2170		LOG_DBG("UUID 0x%s resolved", bt_uuid_str(session->param->uuid));
2171		sdp_client_notify_result(session, UUID_RESOLVED);
2172	iterate:
2173		/* Get next UUID and start resolving it */
2174		sdp_client_params_iterator(session);
2175	
2176		return 0;
2177	}
