2852	static int sdp_get_param_item(struct bt_sdp_uuid_desc *pd_item, uint16_t *param)
2853	{
2854		const uint8_t *p = pd_item->params;
2855		bool len_err = false;
2856	
2857		BT_ASSERT(p);
2858	
2859		LOG_DBG("Getting UUID's 0x%s params", bt_uuid_str(&pd_item->uuid));
2860	
2861		switch (p[0]) {
2862		case BT_SDP_UINT8:
2863			/* check if 8bits value can be read safely */
2864			if (pd_item->params_len < 2) {
2865				len_err = true;
2866				break;
2867			}
2868			*param = (++p)[0];
2869			p += sizeof(uint8_t);
2870			break;
2871		case BT_SDP_UINT16:
2872			/* check if 16bits value can be read safely */
2873			if (pd_item->params_len < 3) {
2874				len_err = true;
2875				break;
2876			}
2877			*param = sys_get_be16(++p);
2878			p += sizeof(uint16_t);
2879			break;
2880		case BT_SDP_UINT32:
2881			/* check if 32bits value can be read safely */
2882			if (pd_item->params_len < 5) {
2883				len_err = true;
2884				break;
2885			}
2886			*param = sys_get_be32(++p);
2887			p += sizeof(uint32_t);
2888			break;
2889		default:
2890			LOG_ERR("Invalid/unhandled DTD 0x%02x\n", p[0]);
2891			return -EINVAL;
2892		}
2893		/*
2894		 * Check if no more data than already read is associated with UUID. In
2895		 * valid case after getting parameter we should reach data buf end.
2896		 */
2897		if (p - pd_item->params != pd_item->params_len || len_err) {
2898			LOG_DBG("Invalid param buffer length");
2899			return -EMSGSIZE;
2900		}
2901	
2902		return 0;
2903	}
