2727	static int sdp_loop_seqs(uint8_t **data, size_t len)
2728	{
2729		ssize_t slen;
2730		ssize_t pre_slen;
2731		uint8_t *end;
2732	
2733		if (len <= 0) {
2734			return -EMSGSIZE;
2735		}
2736	
2737		pre_slen = -EINVAL;
2738		slen = -EINVAL;
2739		end = *data + len;
2740		/* loop all the SEQ */
2741		while (*data < end) {
2742			/* how long is current UUID's item data associated to */
2743			slen = sdp_get_seq_len_item(data, end - *data);
2744			if (slen < 0) {
2745				break;
2746			}
2747			pre_slen = slen;
2748		}
2749	
2750		/* return the last seq len */
2751		if (pre_slen < 0) {
2752			return slen;
2753		}
2754	
2755		return pre_slen;
2756	}
